def kip_surelerini_sinirla(apps, schema_editor):
    """Politika satırının kip sürelerini yeni aralığa çeker (geri göçte değerlere dokunulmaz)."""
    LibraryPolicy = apps.get_model("kutuphane", "LibraryPolicy")
    for satir in LibraryPolicy._base_manager.all():
        bosta = min(max(int(satir.idle_minutes), 1), 15)
        mutlak = min(max(int(satir.admin_max_minutes), 5), 120)
        bosta = min(bosta, mutlak)
        if (bosta, mutlak) != (satir.idle_minutes, satir.admin_max_minutes):
            LibraryPolicy._base_manager.filter(pk=satir.pk).update(
                idle_minutes=bosta, admin_max_minutes=mutlak
            )


